/**
 * Apptivia Engage — Frontend API Client
 * ──────────────────────────────────────
 * Thin wrapper around the backend Engage endpoints and Supabase
 * tables.  Import the hook (useEngage) for React components or
 * use the raw functions directly in utils/services.
 */

import { supabase } from '../supabaseClient';

const BACKEND_URL =
  process.env.REACT_APP_BACKEND_URL ||
  process.env.REACT_APP_SOCKET_IO_URL ||
  'http://localhost:3000';

// ── HTTP helpers ─────────────────────────────────────────────

async function post<T = any>(path: string, body?: Record<string, any>): Promise<T> {
  const res = await fetch(`${BACKEND_URL}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json();
  if (!res.ok || json.error) throw new Error(json.error || res.statusText);
  return json as T;
}

async function get<T = any>(path: string): Promise<T> {
  const res = await fetch(`${BACKEND_URL}${path}`);
  const json = await res.json();
  if (!res.ok || json.error) throw new Error(json.error || res.statusText);
  return json as T;
}

// ── Types ────────────────────────────────────────────────────

